+function escapeRegex(value: string): string {
+  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+}
+
+export function redactSecrets(value: string, secrets: readonly string[] = []): string {
+  // Remove the entire authorization value before generic fields can consume only its scheme.
+  let result = value
+    .replace(/(\bauthorization\b[\s"']*[:=][\s"']*)(?:Bearer|Basic)\s+[^\s&,;"'}]+/gi, "$1[REDACTED]")
+    .replace(/\b(?:Bearer|Basic)\s+[A-Za-z0-9+/_.=-]+/gi, "[REDACTED]")
+    .replace(/(\b(?:authorization|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|key|token)\b[\s"']*[:=][\s"']*)([^\s&,;"'}]+)/gi, "$1[REDACTED]");
+  for (const secret of secrets.filter(Boolean).sort((a, b) => b.length - a.length)) {
+    result = result.split(secret).join("[REDACTED]");
+    // Percent escapes are case-insensitive, but literal characters in a secret are not.
+    const encoded = encodeURIComponent(secret);
+    for (const representation of new Set([encoded, encoded.replace(/%20/g, "+")])) {
+      const pattern = representation.match(/%[0-9a-f]{2}|[^%]+|%/gi)!
+        .map((part) => /^%[0-9a-f]{2}$/i.test(part)
+          ? part.split("").map((character) => /[a-f]/i.test(character) ? `[${character.toLowerCase()}${character.toUpperCase()}]` : character).join("")
+          : escapeRegex(part))
+        .join("");
+      result = result.replace(new RegExp(pattern, "g"), "[REDACTED]");
+    }
+  }
+  return result;
+}
+
+export function errorReport(error: unknown): ProviderError {
+  if (error instanceof ProviderError) return error;
+  return new ProviderError("unreachable", "Provider request failed; no sensitive response details retained.");
+}
+
+function abortError(signal: AbortSignal): ProviderError {
+  return new ProviderError("cancelled", signal.reason?.name === "TimeoutError" ? "Research time limit reached." : "Research cancelled.");
+}
+
+export async function withAbort<T>(work: Promise<T>, signal: AbortSignal): Promise<T> {
+  if (signal.aborted) {
+    // Work may already have started, including a noncooperative transport's later rejection.
+    void work.catch(() => {});
+    throw abortError(signal);
+  }
+  let listener: () => void = () => {};
+  try {
+    return await Promise.race([work, new Promise<never>((_, reject) => {
+      listener = () => reject(abortError(signal));
+      signal.addEventListener("abort", listener, { once: true });
+      if (signal.aborted) listener();
+    })]);
+  } finally {
+    signal.removeEventListener("abort", listener);
+  }
+}
+
+function delay(ms: number, signal: AbortSignal): Promise<void> {
+  if (signal.aborted) return Promise.reject(abortError(signal));
+  return new Promise((resolve, reject) => {
+    const finish = () => {
+      signal.removeEventListener("abort", abort);
+      resolve();
+    };
+    const timer = setTimeout(finish, ms);
+    timer.unref?.();
+    const abort = () => {
+      clearTimeout(timer);
+      signal.removeEventListener("abort", abort);
+      reject(abortError(signal));
+    };
+    signal.addEventListener("abort", abort, { once: true });
+    if (signal.aborted) abort();
+  });
+}
